ep="0.01" min="0.01" name="subjects[{{ $i }}][max_marks]" value="{{ $row['max_marks'] ?? 100 }}" class="form-control" required></td><td><input type="number" step="0.01" min="0" name="subjects[{{ $i }}][marks_obtained]" value="{{ $row['marks_obtained'] ?? '' }}" class="form-control" required></td><td><input name="subjects[{{ $i }}][remark]" value="{{ $row['remark'] ?? '' }}" class="form-control"></td><td class="text-center"><button type="button" class="btn btn-sm btn-outline-danger remove-subject-row"><i class="fa-solid fa-trash"></i></button></td></tr>@endforeach</tbody></table></div><div class="d-flex justify-content-end"><button class="btn btn-primary px-4">Save All Subjects</button></div></form></div></div>
<script>
document.addEventListener('DOMContentLoaded',function(){const tbody=document.getElementById('subjectRows');const addBtn=document.getElementById('addSubjectRow');function reindexRows(){tbody.querySelectorAll('.subject-row').forEach(function(row,index){row.querySelectorAll('input').forEach(function(input){input.name=input.name.replace(/subjects\[\d+\]/,'subjects['+index+']');});});}function updateRemoveButtons(){const rows=tbody.querySelectorAll('.subject-row');rows.forEach(function(row){const btn=row.querySelector('.remove-subject-row');btn.disabled=rows.length===1;});}addBtn.addEventListener('click',function(){const index=tbody.querySelectorAll('.subject-row').length;const tr=document.createElement('tr');tr.className='subject-row';tr.innerHTML='<td><input name="subjects['+index+'][subject]" class="form-control subject-input" required></td><td><input type="number" step="0.01" min="0.01" name="subjects['+index+'][max_marks]" value="100" class="form-control" required></td><td><input type="number" step="0.01" min="0" name="subjects['+index+'][marks_obtained]" class="form-control" required></td><td><input name="subjects['+index+'][remark]" class="form-control"></td><td class="text-center"><button type="button" class="btn btn-sm btn-outline-danger remove-subject-row"><i class="fa-solid fa-trash"></i></button></td>';tbody.appendChild(tr);updateRemoveButtons();tr.querySelector('.subject-input').focus();});tbody.addEventListener('click',function(event){const btn=event.target.closest('.remove-subject-row');if(!btn)return;if(tbody.querySelectorAll('.subject-row').length===1)return;btn.closest('.subject-row').remove();reindexRows();updateRemoveButtons();});updateRemoveButtons();});
</script>
